const response = items[0].json.message.content;

const subjectMatch = response.match(/EMAIL[\s_]SUBJECT:\s*(.*)/i);

const bodyRegex = /EMAIL[\s_]BODY:/gi;
let lastIndex = -1, match;
while ((match = bodyRegex.exec(response)) !== null) {
  lastIndex = match.index + match[0].length;
}

const checkoutRow = $('Get Checkout Row 2').first().json;

const email_subject = subjectMatch ? subjectMatch[1].trim().replace(/^["']|["']$/g, '') : 'Still thinking it over?';

let raw_body = lastIndex !== -1 ? response.slice(lastIndex).trim() : '';
if (!raw_body) raw_body = `Your ${checkoutRow.Product} ($${checkoutRow.Price}) is still waiting for you.`;

raw_body = raw_body.replace(/^(Dear|Hi|Hello|Hey)\b[^.!?\n]{0,30}[.!?]\s*/i, '');
raw_body = raw_body.replace(/\n*\b(Best regards|Sincerely|Warm regards)\b[\s\S]*$/i, '').trim();

const cleaned = raw_body
  .replace(/\r\n/g, '\n')
  .replace(/\n{2,}/g, '\n\n')
  .split('\n\n')
  .map(p => p.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim())
  .filter(p => p.length > 0)
  .join('<br><br>');

const companyName = 'StrideWell Footwear';

const email_body = `Hi there,<br><br>${cleaned}<br><br><a href="${checkoutRow['Recovery Link']}">Complete your order</a><br><br>Best regards,<br>${companyName} Team`;

return [{
  json: {
    email_subject,
    email_body,
    to_email: checkoutRow.Email
  }
}];

