const response = items[0].json.message.content;

const subjectMatch = response.match(/EMAIL[\s_]SUBJECT:\s*(.*)/i);

const bodyRegex = /EMAIL[\s_]BODY:/gi;
let lastIndex = -1, match;
while ((match = bodyRegex.exec(response)) !== null) {
  lastIndex = match.index + match[0].length;
}

const upsellData = $('Pick Upsell').first().json;

const email_subject = subjectMatch ? subjectMatch[1].trim().replace(/^["']|["']$/g, '') : 'Thanks for your order!';

let raw_body = lastIndex !== -1 ? response.slice(lastIndex).trim() : '';
if (!raw_body) raw_body = `Thanks for your order! You might also like our ${upsellData.upsell_product} ($${upsellData.upsell_price}).`;

raw_body = raw_body.replace(/^(Dear|Hi|Hello|Hey)\b[^.!?\n]{0,30}[.!?]\s*/i, '');
raw_body = raw_body.replace(/\n*\b(Best regards|Sincerely|Warm regards)\b[\s\S]*$/i, '').trim();

const cleaned = raw_body
  .replace(/\r\n/g, '\n')
  .replace(/\n{2,}/g, '\n\n')
  .split('\n\n')
  .map(p => p.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim())
  .filter(p => p.length > 0)
  .join('<br><br>');

const companyName = 'StrideWell Footwear';

const email_body = `Hi there,<br><br>${cleaned}<br><br>Best regards,<br>${companyName} Team`;

return [{
  json: {
    email_subject,
    email_body,
    to_email: upsellData.email
  }
}];

const catalog = [
  { name: 'Trail Runner Pro', price: 89.99 },
  { name: 'Classic Canvas Sneaker', price: 54.99 },
  { name: 'All-Day Comfort Slip-On', price: 64.99 }
];

const purchased = items[0].json.Product;
const email = items[0].json.Email;
const purchasedPrice = items[0].json.Price;

const upsellOptions = catalog.filter(p => p.name !== purchased);
const upsell = upsellOptions[Math.floor(Math.random() * upsellOptions.length)];

return [{
  json: {
    purchased_product: purchased,
    purchased_price: purchasedPrice,
    email,
    upsell_product: upsell.name,
    upsell_price: upsell.price
  }
}];

const rows = items.map(item => item.json);

const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const thisWeekRows = rows.filter(row => {
  const created = new Date(row['Created At']);
  return created >= sevenDaysAgo && created <= now;
});

const recoveredRows = thisWeekRows.filter(row => row['Status'] === 'Recovered');

const totalAbandoned = thisWeekRows.length;
const totalRecovered = recoveredRows.length;
const revenueRecovered = recoveredRows.reduce((sum, row) => sum + Number(row['Price'] || 0), 0);
const recoveryRate = totalAbandoned > 0 ? Math.round((totalRecovered / totalAbandoned) * 100) : 0;

const email_subject = `Cart Recovery Summary — $${revenueRecovered.toFixed(2)} Recovered This Week`;

const email_body = `Here's your cart recovery summary for the past 7 days:<br><br><strong>$${revenueRecovered.toFixed(2)} recovered</strong> from ${totalRecovered} cart${totalRecovered === 1 ? '' : 's'}<br>${totalAbandoned} total cart${totalAbandoned === 1 ? '' : 's'} abandoned<br>${recoveryRate}% recovery rate<br><br>StrideWell Footwear — Cart Recovery Agent`;

return [{ json: { email_subject, email_body } }];

